    transition, with its nonce accruing normally.

    Asserting that final nonce is what catches the glamsterdam-devnet-6 bug: a
    client that re-injects EIP-7997 at the transition resets the already-used
    factory back to nonce 1, diverging the post-state root. Deployment success
    alone cannot catch it, since the `CREATE2` address does not depend on the
    factory nonce.
    """
    factory = pre.deploy_contract(
        code=Spec.FACTORY_BYTECODE,
        address=Address(Spec.FACTORY_ADDRESS),
        nonce=pre_fork_nonce,
    )
    sender = pre.fund_eoa()

    runtime_code = Op.RETURN(0, 1)
    initcode = Initcode(deploy_code=runtime_code)

    timestamps = [FORK_TIMESTAMP - 1, FORK_TIMESTAMP, FORK_TIMESTAMP + 1]

    blocks = []
    deployed = {}
    for i, timestamp in enumerate(timestamps):
        blocks.append(
            Block(
                timestamp=timestamp,
                txs=[
                    Transaction(
                        sender=sender,
                        to=factory,
                        data=Hash(timestamp) + bytes(initcode),
                    )
                ],
                expected_block_access_list=BlockAccessListExpectation(
                    account_expectations={
                        factory: BalAccountExpectation(
                            nonce_changes=[
                                BalNonceChange(
                                    block_access_index=1,
                                    post_nonce=pre_fork_nonce + i + 1,
                                )
                            ],
                        ),
                    }
                ),
            )
        )
        deployed[compute_create2_address(factory, timestamp, initcode)] = (
            Account(nonce=1, code=bytes(runtime_code))
        )

    blockchain_test(
        pre=pre,
        blocks=blocks,
        post={
            **deployed,
            factory: Account(
                nonce=pre_fork_nonce + len(timestamps),
                code=Spec.FACTORY_BYTECODE,
            ),
        },
    )


@pytest.mark.valid_at_transition_to("Amsterdam")
@pytest.mark.pre_alloc_mutable
def test_factory_absent_across_transition(
    blockchain_test: BlockchainTestFiller,
    pre: Alloc,
) -> None:
    """
    A chain that never deployed the factory transitions to Amsterdam
    through valid blocks, and the factory address stays nonexistent.

    The client MUST NOT check for the existence of the contract at
    the fork boundary. Therefore, we verify that the BAL does
    not contain the factory account read.
    The block itself is valid. It is the responsibility of the
    chain activating EIP-7997 to ensure the factory is valid
    at the start of the fork block.
    """
    factory = Address(Spec.FACTORY_ADDRESS)
    # Merging an all-zero account into the fork's pre-allocation removes
    # the factory predeploy from the genesis allocation entirely.
    pre[factory] = Account(nonce=0, balance=0, code=b"")

    sender = pre.fund_eoa()
    receiver = pre.fund_eoa(amount=0)
    transfer_value = 1

    timestamps = [FORK_TIMESTAMP - 1, FORK_TIMESTAMP, FORK_TIMESTAMP + 1]

    blocks = []
    for i, timestamp in enumerate(timestamps):
        blocks.append(
            Block(
                timestamp=timestamp,
                txs=[
                    Transaction(
                        sender=sender,
                        to=receiver,
                        value=transfer_value,
                    )
                ],
                expected_block_access_list=BlockAccessListExpectation(
                    account_expectations={
                        factory: None,
                        sender: BalAccountExpectation(
                            nonce_changes=[
                                BalNonceChange(
                                    block_access_index=1,
                                    post_nonce=i + 1,
                                )
                            ],
                        ),
                    }
                )
                if timestamp >= FORK_TIMESTAMP
                else None,
            )
        )

    blockchain_test(
        pre=pre,
        blocks=blocks,
        post={
            factory: Account.NONEXISTENT,
            receiver: Account(balance=len(timestamps) * transfer_value),
        },
    )

"""
EIP-7997: Deterministic Factory Predeploy.

Predeploy the Arachnid `CREATE2` factory at
`0x4e59b44847b379578588920ca78fbf26c0b4956c` so deterministic
deployments are available across chains without bootstrapping
transactions.

https://eips.ethereum.org/EIPS/eip-7997
"""

from typing import Mapping

from execution_testing.base_types import Address

from ....base_fork import BaseFork

DETERMINISTIC_FACTORY_PREDEPLOY_ADDRESS = (
    0x4E59B44847B379578588920CA78FBF26C0B4956C
)
DETERMINISTIC_FACTORY_PREDEPLOY_BYTECODE = bytes.fromhex(
    "7fffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffe0"
    "3601600081602082378035828234f58015156039578182fd"
    "5b8082525050506014600cf3"
)


class EIP7997(BaseFork):
    """EIP-7997 class."""

    @classmethod
    def deterministic_factory_predeploy_address(cls) -> Address | None:
        """Return the EIP-7997 deterministic factory predeploy address."""
        return Address(
            DETERMINISTIC_FACTORY_PREDEPLOY_ADDRESS,
            label="DETERMINISTIC_FACTORY_PREDEPLOY_ADDRESS",
        )

    @classmethod
    def pre_allocation(cls) -> Mapping:
        """Pre-allocate the deterministic factory predeploy."""
        return {
            DETERMINISTIC_FACTORY_PREDEPLOY_ADDRESS: {
                "nonce": 1,
                "code": DETERMINISTIC_FACTORY_PREDEPLOY_BYTECODE,
            }
        } | super(EIP7997, cls).pre_allocation()  # type: ignore

    @classmethod
    def pre_allocation_blockchain(cls) -> Mapping:
        """Pre-allocate the deterministic factory predeploy."""
        return {
            DETERMINISTIC_FACTORY_PREDEPLOY_ADDRESS: {
                "nonce": 1,
                "code": DETERMINISTIC_FACTORY_PREDEPLOY_BYTECODE,
            }
        } | super(EIP7997, cls).pre_allocation_blockchain()  # type: ignore

"""
EIP-8282: Builder Execution Requests.

Predeploy builder deposit and exit request contracts for EIP-7732 builders on
the EIP-7685 request bus.

https://eips.ethereum.org/EIPS/eip-8282
"""

from typing import List, Mapping

from execution_testing.base_types import Address

from ....base_fork import BaseFork
from ....bytecode import load_contract_bytecode

BUILDER_DEPOSIT_CONTRACT_ADDRESS = 0x0000BFF46984E3725691FA540A8C7589300D8282
BUILDER_DEPOSIT_CONTRACT_BYTECODE = load_contract_bytecode(
    __name__, "builder_deposit_request.bin"
)

BUILDER_EXIT_CONTRACT_ADDRESS = 0x000064D678505AD48F8CCB093BC65613800E8282
BUILDER_EXIT_CONTRACT_BYTECODE = load_contract_bytecode(
    __name__, "builder_exit_request.bin"
)


class EIP8282(BaseFork):
    """EIP-8282 class."""

    @classmethod
    def max_request_type(cls) -> int:
        """
        Two request types are introduced: builder deposit requests (0x03)
        and builder exit requests (0x04).
        """
        return super(EIP8282, cls).max_request_type() + 2

    @classmethod
    def empty_block_bal_item_count(cls) -> int:
        """Add block-level access list elements for an empty block."""
        # Builder contracts: 2 addresses + 8 reads = 10
        return super(EIP8282, cls).empty_block_bal_item_count() + 10

    @classmethod
    def system_contracts(cls) -> List[Address]:
        """Add the builder deposit and exit request predeploy contracts."""
        return [
            Address(
                BUILDER_DEPOSIT_CONTRACT_ADDRESS,
                label="BUILDER_DEPOSIT_CONTRACT_ADDRESS",
            ),
            Address(
                BUILDER_EXIT_CONTRACT_ADDRESS,
                label="BUILDER_EXIT_CONTRACT_ADDRESS",
            ),
        ] + super(EIP8282, cls).system_contracts()

    @classmethod
    def pre_allocation_blockchain(cls) -> Mapping:
        """Pre-allocate the builder deposit and exit request contracts."""
        return {
            BUILDER_DEPOSIT_CONTRACT_ADDRESS: {
                "nonce": 1,
                "code": BUILDER_DEPOSIT_CONTRACT_BYTECODE,
            },
            BUILDER_EXIT_CONTRACT_ADDRESS: {
                "nonce": 1,
                "code": BUILDER_EXIT_CONTRACT_BYTECODE,
            },
            **super(EIP8282, cls).pre_allocation_blockchain(),
        }
